Lemma u8_feeds_app : forall v l1 l2, u8_feeds v (l1 ++ l2) = u8_feeds (u8_feeds v l1) l2.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1+1+2%v;R+0%l2;R0!3+4+0!2'5#2!3'6+2#3#1!2'5!2'5#2#3#1!1,8+2!3,:+2#5#4$v;R+0$l1;R0!6'3+2$l1;R01$v;R+0$l2;R0vd!2,7+0!2'5#2#1!3+4+0!2'5#2!3'6+22#1!2'5!2'5#22#1$b;R+2$r;R0$IH;R1$v;R+0$l2;R0vd!2#3!2'9#2#5#1!3+4+0!2'5#2!3'6+23#1!2'5!2'5#23#1#1#2").
Qed.
Lemma b256_app : forall l1 l2, b256 (l1 ++ l2) = b256 l1 ++ b256 l2.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1+1+2$l1;R0$l2;R0vd!5';+2+2$b;R+2!2'<#1!1,=|800;#2#1!3+40!1'>!3'6+2#2#1!3'6+2!1'>#2!1'>#1").
Qed.
Lemma b256_firstn : forall n l, b256 (firstn n l) = firstn n (b256 l).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S41lg@bd;g?d;!1+1+2$b;R+2!2'<#1!1,=|800;!3'C+2#2#1!4'B+2+212$n;R+A$l;R0vd!6'?03$l;R0!3+40!4'B+2+21!3'C+2#3#2#1!2,703!3'C+2#2!4'B+2+21#1!5'@+2+21#2#1!3+40!1'>2!3'C+2#2!1'>#1").
