Section SimSound.
Variable ab : nat -> Z.
Hypothesis Hab : forall k, inb (ab k).
Variable rt : RT.
Variable avail : nat.
Hypothesis HRT : forall k q, (k < avail)%nat -> In (canonq q (ab k)) (rget rt k q).
Definition arun (va : u8v) (k m : nat) : u8v := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S00$va;R+0$k;R+A$m;R+A!2'5#3!4'B+A+2/ab;!2'`=#2!2'cK#1#2").
Lemma arun_nil : forall va k, arun va k k = va.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$va;R+0$k;R+Avd!6'?+A,^Z$n;R+A!3+4+0!2'5#3!4'B+A+2/ab;!2'`=#2#1#3!2,7+0#2!2'cL#1#1!1'cM#1!3+4+0!3'cN#2#1#1#2").
