Lemma link_byte : forall cells k v E' (Mv M' : mem) p w (n0 : nat),
  link cells k = Some v -> know_ok RSEGS E' Mv cells -> (forall a b, L5.u8_at RSEGS Mv a b -> L5.u8_at RSEGS M' a b) ->
  L5.bytes_at RSEGS M' p w -> Forall inb w -> uv E' CUR = p + Z.of_nat n0 -> 0 <= k -> (n0 + Z.to_nat k < length w)%nat ->
