Section Leaf.
Variable cells : list kentry.
Variable al : list (nat * nat).
Variable vc : list (nat * Z * Z).
Variable E' : env.
Variables Mv M' : mem.
Variables p len : Z.
Variable w : list Z.
Variable n0 : nat.
Hypothesis HK : know_ok RSEGS E' Mv cells.
Hypothesis HI : kentry_ok RSEGS E' Mv (KImg ILO IHI).
Hypothesis U8F : forall a b, L5.u8_at RSEGS Mv a b -> L5.u8_at RSEGS M' a b.
Hypothesis HB : L5.bytes_at RSEGS M' p w.
Hypothesis HF : Forall inb w.
Hypothesis HLEN : Z.of_nat (length w) = len.
Hypothesis HPW : p + len < 2 ^ 64.
Hypothesis HCUR : uv E' CUR = p + Z.of_nat n0.
Hypothesis HJ : uv E' JV = len - Z.of_nat n0.
Hypothesis HN0 : Z.of_nat n0 <= len.
Hypothesis ALI : forall k v, In (k, v) al -> uv E' (EVar v) = nth (n0 + k) w 0.
Hypothesis VCI : Forall (fun e : nat * Z * Z => match e with (k, lo, hi) => lo <= nth (n0 + k) w 0 <= hi end) vc.
(* [comment removed for export] *)
