Theorem step_sound : forall sti sg stj (alj : bool) vcj,
  step_chk sti al vc cells sg stj alj vcj = true ->
  u8_feeds u8_init (b256 (firstn (n0 + sti) w)) = u8_init ->
  exists d : nat, uv E' (CC.slook sg 40) = len - Z.of_nat (n0 + d) /\ Z.of_nat (n0 + d) + Z.of_nat stj <= len /\
    u8_feeds u8_init (b256 (firstn (n0 + d + stj) w)) = u8_init /\
